{"file_path": "src/components/CVForm.tsx", "initial_content": "import { useState } from 'react'
import PersonalInfoForm from './forms/PersonalInfoForm'
import WorkExperienceForm from './forms/WorkExperienceForm'
import EducationForm from './forms/EducationForm'
import SkillsForm from './forms/SkillsForm'
import CertificationsForm from './forms/CertificationsForm'
import ProjectsForm from './forms/ProjectsForm'
import LanguagesForm from './forms/LanguagesForm'
import { ChevronDown, ChevronUp } from 'lucide-react'

interface Section {
  id: string
  title: string
  component: React.ComponentType
  isOpen: boolean
}

export default function CVForm() {
  const [sections, setSections] = useState<Section[]>([
    { id: 'personal', title: 'Personal Information', component: PersonalInfoForm, isOpen: true },
    { id: 'experience', title: 'Work Experience', component: WorkExperienceForm, isOpen: true },
    { id: 'education', title: 'Education', component: EducationForm, isOpen: true },
    { id: 'skills', title: 'Skills', component: SkillsForm, isOpen: true },
    { id: 'projects', title: 'Projects', component: ProjectsForm, isOpen: false },
    { id: 'certifications', title: 'Certifications', component: CertificationsForm, isOpen: false },
    { id: 'languages', title: 'Languages', component: LanguagesForm, isOpen: false },
  ])

  const toggleSection = (id: string) => {
    setSections(prev =>
      prev.map(section =>
        section.id === id ? { ...section, isOpen: !section.isOpen } : section
      )
    )
  }

  return (
    <div className="space-y-4">
      {sections.map(section => {
        const Component = section.component
        return (
          <div key={section.id} className="card">
            <button
              onClick={() => toggleSection(section.id)}
              className="w-full flex items-center justify-between mb-4 text-left"
            >
              <h2 className="text-xl font-semibold text-gray-800">{section.title}</h2>
              {section.isOpen ? (
                <ChevronUp className="w-5 h-5 text-gray-500" />
              ) : (
                <ChevronDown className="w-5 h-5 text-gray-500" />
              )}
            </button>
            {section.isOpen && <Component />}
          </div>
        )
      })}
    </div>
  )
}
"}

{"file_path": "src/components/forms/SkillsForm.tsx", "initial_content": "import { useState } from 'react'
import { useCV } from '../../contexts/CVContext'
import { generateId } from '../../utils/helpers'
import { Plus, X } from 'lucide-react'
import { Skill } from '../../types/cv'

export default function SkillsForm() {
  const { cvData, addSkill, deleteSkill } = useCV()
  const [skillName, setSkillName] = useState('')
  const [category, setCategory] = useState<Skill['category']>('technical')
  const [level, setLevel] = useState<Skill['level']>('intermediate')

  const handleAdd = () => {
    if (!skillName.trim()) return

    const newSkill: Skill = {
      id: generateId(),
      name: skillName.trim(),
      category,
      level,
    }

    addSkill(newSkill)
    setSkillName('')
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      handleAdd()
    }
  }

  const groupedSkills = cvData.skills.reduce((acc, skill) => {
    if (!acc[skill.category]) {
      acc[skill.category] = []
    }
    acc[skill.category].push(skill)
    return acc
  }, {} as Record<string, Skill[]>)

  const categoryLabels = {
    technical: 'Technical Skills',
    soft: 'Soft Skills',
    language: 'Language Skills',
    other: 'Other Skills',
  }

  return (
    <div className="space-y-6">
      {/* Add Skill Form */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
        <div className="md:col-span-2">
          <label className="label-text">Skill Name</label>
          <input
            type="text"
            value={skillName}
            onChange={(e) => setSkillName(e.target.value)}
            onKeyPress={handleKeyPress}
            className="input-field"
            placeholder="e.g., JavaScript, Leadership"
          />
        </div>
        <div>
          <label className="label-text">Category</label>
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value as Skill['category'])}
            className="input-field"
          >
            <option value="technical">Technical</option>
            <option value="soft">Soft Skills</option>
            <option value="language">Language</option>
            <option value="other">Other</option>
          </select>
        </div>
        <div>
          <label className="label-text">Level</label>
          <select
            value={level}
            onChange={(e) => setLevel(e.target.value as Skill['level'])}
            className="input-field"
          >
            <option value="beginner">Beginner</option>
            <option value="intermediate">Intermediate</option>
            <option value="advanced">Advanced</option>
            <option value="expert">Expert</option>
          </select>
        </div>
      </div>

      <button
        onClick={handleAdd}
        className="btn-primary flex items-center gap-2"
      >
        <Plus className="w-4 h-4" />
        Add Skill
      </button>

      {/* Display Skills by Category */}
      <div className="space-y-4">
        {Object.entries(groupedSkills).map(([cat, skills]) => (
          <div key={cat}>
            <h3 className="text-sm font-semibold text-gray-700 mb-2">
              {categoryLabels[cat as Skill['category']]}
            </h3>
            <div className="flex flex-wrap gap-2">
              {skills.map((skill) => (
                <div
                  key={skill.id}
                  className="inline-flex items-center gap-2 px-3 py-1.5 bg-primary-100 text-primary-800 rounded-full text-sm"
                >
                  <span>
                    {skill.name}
                    {skill.level && (
                      <span className="ml-1 text-xs opacity-75">
                        ({skill.level})
                      </span>
                    )}
                  </span>
                  <button
                    onClick={() => deleteSkill(skill.id)}
                    className="hover:text-red-600"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {cvData.skills.length === 0 && (
        <p className="text-center text-gray-500 py-8">
          No skills added yet. Add your first skill above!
        </p>
      )}
    </div>
  )
}
"}

{"file_path": "src/components/forms/ProjectsForm.tsx", "initial_content": "import { useState } from 'react'
import { useCV } from '../../contexts/CVContext'
import { generateId } from '../../utils/helpers'
import { Plus, Trash2, Edit2, Check, X } from 'lucide-react'
import { Project } from '../../types/cv'

export default function ProjectsForm() {
  const { cvData, addProject, updateProject, deleteProject } = useCV()
  const [isAdding, setIsAdding] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [formData, setFormData] = useState<Partial<Project>>({})
  const [techInput, setTechInput] = useState('')

  const resetForm = () => {
    setFormData({})
    setIsAdding(false)
    setEditingId(null)
    setTechInput('')
  }

  const handleSubmit = () => {
    if (!formData.name || !formData.description) return

    const data: Project = {
      id: editingId || generateId(),
      name: formData.name || '',
      description: formData.description || '',
      technologies: formData.technologies || [],
      url: formData.url,
      github: formData.github,
      startDate: formData.startDate || '',
      endDate: formData.endDate,
    }

    if (editingId) {
      updateProject(editingId, data)
    } else {
      addProject(data)
    }
    resetForm()
  }

  const handleEdit = (project: Project) => {
    setFormData(project)
    setEditingId(project.id)
    setIsAdding(true)
  }

  const addTechnology = () => {
    if (!techInput.trim()) return
    const technologies = formData.technologies || []
    setFormData({ ...formData, technologies: [...technologies, techInput.trim()] })
    setTechInput('')
  }

  const removeTechnology = (index: number) => {
    const technologies = formData.technologies || []
    setFormData({
      ...formData,
      technologies: technologies.filter((_, i) => i !== index),
    })
  }

  return (
    <div className="space-y-4">
      {cvData.projects.map((project) => (
        <div key={project.id} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
          <div className="flex justify-between items-start">
            <div className="flex-1">
              <h3 className="font-semibold text-gray-900">{project.name}</h3>
              <p className="text-sm text-gray-600 mt-1">{project.description}</p>
              {project.technologies.length > 0 && (
                <div className="flex flex-wrap gap-1 mt-2">
                  {project.technologies.map((tech, idx) => (
                    <span
                      key={idx}
                      className="px-2 py-0.5 bg-blue-100 text-blue-800 text-xs rounded"
                    >
                      {tech}
                    </span>
                  ))}
                </div>
              )}
              {(project.url || project.github) && (
                <div className="flex gap-3 mt-2 text-xs text-primary-600">
                  {project.url && <a href={project.url} target="_blank" rel="noopener noreferrer">Live Demo</a>}
                  {project.github && <a href={project.github} target="_blank" rel="noopener noreferrer">GitHub</a>}
                </div>
              )}
            </div>
            <div className="flex gap-2">
              <button
                onClick={() => handleEdit(project)}
                className="p-1 text-gray-500 hover:text-primary-600"
              >
                <Edit2 className="w-4 h-4" />
              </button>
              <button
                onClick={() => deleteProject(project.id)}
                className="p-1 text-gray-500 hover:text-red-600"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      ))}

      {!isAdding && (
        <button
          onClick={() => setIsAdding(true)}
          className="w-full py-3 border-2 border-dashed border-gray-300 rounded-lg text-gray-600 hover:border-primary-500 hover:text-primary-600 transition-colors flex items-center justify-center gap-2"
        >
          <Plus className="w-5 h-5" />
          Add Project
        </button>
      )}

      {isAdding && (
        <div className="p-4 bg-blue-50 rounded-lg border border-blue-200 space-y-4">
          <div>
            <label className="label-text">Project Name *</label>
            <input
              type="text"
              value={formData.name || ''}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="input-field"
              placeholder="My Awesome Project"
            />
          </div>

          <div>
            <label className="label-text">Description *</label>
            <textarea
              value={formData.description || ''}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="input-field resize-none"
              rows={3}
              placeholder="Brief description of the project..."
            />
          </div>

          <div>
            <label className="label-text">Technologies</label>
            <div className="flex gap-2">
              <input
                type="text"
                value={techInput}
                onChange={(e) => setTechInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), addTechnology())}
                className="input-field"
                placeholder="e.g., React, Node.js"
              />
              <button
                onClick={addTechnology}
                className="btn-secondary"
              >
                <Plus className="w-4 h-4" />
              </button>
            </div>
            {formData.technologies && formData.technologies.length > 0 && (
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.technologies.map((tech, idx) => (
                  <span
                    key={idx}
                    className="inline-flex items-center gap-1 px-2 py-1 bg-blue-100 text-blue-800 text-sm rounded"
                  >
                    {tech}
                    <button onClick={() => removeTechnology(idx)}>
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}
              </div>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="label-text">Project URL</label>
              <input
                type="url"
                value={formData.url || ''}
                onChange={(e) => setFormData({ ...formData, url: e.target.value })}
                className="input-field"
                placeholder="https://project.com"
              />
            </div>
            <div>
              <label className="label-text">GitHub URL</label>
              <input
                type="url"
                value={formData.github || ''}
                onChange={(e) => setFormData({ ...formData, github: e.target.value })}
                className="input-field"
                placeholder="https://github.com/user/repo"
              />
            </div>
          </div>

          <div className="flex gap-2">
            <button onClick={handleSubmit} className="btn-primary flex items-center gap-2">
              <Check className="w-4 h-4" />
              {editingId ? 'Update' : 'Add'}
            </button>
            <button onClick={resetForm} className="btn-secondary flex items-center gap-2">
              <X className="w-4 h-4" />
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  )
}
"}

{"file_path": "src/components/forms/LanguagesForm.tsx", "initial_content": "import { useState } from 'react'
import { useCV } from '../../contexts/CVContext'
import { generateId } from '../../utils/helpers'
import { Plus, Trash2 } from 'lucide-react'
import { Language } from '../../types/cv'

export default function LanguagesForm() {
  const { cvData, addLanguage, deleteLanguage } = useCV()
  const [languageName, setLanguageName] = useState('')
  const [proficiency, setProficiency] = useState<Language['proficiency']>('intermediate')

  const handleAdd = () => {
    if (!languageName.trim()) return

    const newLanguage: Language = {
      id: generateId(),
      name: languageName.trim(),
      proficiency,
    }

    addLanguage(newLanguage)
    setLanguageName('')
  }

  const proficiencyLabels = {
    native: 'Native',
    fluent: 'Fluent',
    professional: 'Professional',
    intermediate: 'Intermediate',
    basic: 'Basic',
  }

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="md:col-span-2">
          <label className="label-text">Language</label>
          <input
            type="text"
            value={languageName}
            onChange={(e) => setLanguageName(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), handleAdd())}
            className="input-field"
            placeholder="e.g., English, Spanish"
          />
        </div>
        <div>
          <label className="label-text">Proficiency</label>
          <select
            value={proficiency}
            onChange={(e) => setProficiency(e.target.value as Language['proficiency'])}
            className="input-field"
          >
            <option value="native">Native</option>
            <option value="fluent">Fluent</option>
            <option value="professional">Professional</option>
            <option value="intermediate">Intermediate</option>
            <option value="basic">Basic</option>
          </select>
        </div>
      </div>

      <button
        onClick={handleAdd}
        className="btn-primary flex items-center gap-2"
      >
        <Plus className="w-4 h-4" />
        Add Language
      </button>

      {cvData.languages.length > 0 && (
        <div className="space-y-2">
          {cvData.languages.map((lang) => (
            <div
              key={lang.id}
              className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200"
            >
              <div>
                <span className="font-medium text-gray-900">{lang.name}</span>
                <span className="ml-2 text-sm text-gray-600">
                  • {proficiencyLabels[lang.proficiency]}
                </span>
              </div>
              <button
                onClick={() => deleteLanguage(lang.id)}
                className="p-1 text-gray-500 hover:text-red-600"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
      )}

      {cvData.languages.length === 0 && (
        <p className="text-center text-gray-500 py-8">
          No languages added yet. Add your first language above!
        </p>
      )}
    </div>
  )
}
"}

