{"file_path": "src/components/ExportButton.tsx", "initial_content": "import { useState } from 'react'
import { useCV } from '../contexts/CVContext'
import { Download, Loader2 } from 'lucide-react'
import { exportToPDF } from '../utils/pdfExport'

export default function ExportButton() {
  const { cvData } = useCV()
  const [isExporting, setIsExporting] = useState(false)

  const handleExport = async () => {
    setIsExporting(true)
    try {
      await exportToPDF(cvData)
    } catch (error) {
      console.error('Failed to export PDF:', error)
      alert('Failed to export PDF. Please try again.')
    } finally {
      setIsExporting(false)
    }
  }

  return (
    <button
      onClick={handleExport}
      disabled={isExporting}
      className="btn-primary flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
    >
      {isExporting ? (
        <>
          <Loader2 className="w-5 h-5 animate-spin" />
          Generating PDF...
        </>
      ) : (
        <>
          <Download className="w-5 h-5" />
          Export to PDF
        </>
      )}
    </button>
  )
}
"}

{"file_path": "src/utils/pdfExport.ts", "initial_content": "import html2canvas from 'html2canvas'
import jsPDF from 'jspdf'
import { CVState } from '../types/cv'

export async function exportToPDF(cvData: CVState): Promise<void> {
  const cvElement = document.getElementById('cv-preview')

  if (!cvElement) {
    throw new Error('CV preview element not found')
  }

  // Get the full name for the filename, or use default
  const fileName = cvData.personalInfo.fullName 
    ? `${cvData.personalInfo.fullName.replace(/\s+/g, '_')}_CV.pdf`
    : 'CV.pdf'

  try {
    // Capture the CV element as canvas
    const canvas = await html2canvas(cvElement, {
      scale: 2, // Higher quality
      useCORS: true,
      logging: false,
      backgroundColor: '#ffffff',
    })

    // Calculate PDF dimensions
    const imgWidth = 210 // A4 width in mm
    const pageHeight = 297 // A4 height in mm
    const imgHeight = (canvas.height * imgWidth) / canvas.width
    let heightLeft = imgHeight
    let position = 0

    // Create PDF
    const pdf = new jsPDF('p', 'mm', 'a4')
    const imgData = canvas.toDataURL('image/png')

    // Add first page
    pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight)
    heightLeft -= pageHeight

    // Add additional pages if needed
    while (heightLeft > 0) {
      position = heightLeft - imgHeight
      pdf.addPage()
      pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight)
      heightLeft -= pageHeight
    }

    // Save the PDF
    pdf.save(fileName)
  } catch (error) {
    console.error('Error generating PDF:', error)
    throw error
  }
}
"}

